// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        // actor must be an EOA-like caller with no token balance initially; use a wide domain.
        vm.assume(actor != address(0));
        // actor needs to support the Nu Token; normal EOAs cannot call supportsToken,
        // so the only admissible caller is the Bank contract address itself (or a contract exposing that function).
        // Deploy a minimal Bank that returns the right bytes32, and use it as caller.
        Bank b = new Bank();
        vm.prank(address(b));
        c.airDrop();
        // The reference unlocks after the guarded body; the mutant leaves _locked true forever.
        assertTrue(!c._locked());
    }
}
